CREATE VIEW "Z_TEST_PRODUCTION_20250925"."B1_InvPostListILWithoutBinView" ( "LogEntry", "ApplyType", "ApplyEntry", "ApplyLine", "AppSubLine", "LocCode", "ItemCode", "ManagedBy", "MdAbsEntry", "Quantity" ) AS ((SELECT T0."LogEntry", T0."ApplyType", T0."ApplyEntry", T0."ApplyLine", T0."AppSubLine", T0."LocCode", T0."ItemCode", T0."ManagedBy", T1."MdAbsEntry", T1."Quantity" FROM  "Z_TEST_PRODUCTION_20250925"."OITL" T0   LEFT OUTER  JOIN "Z_TEST_PRODUCTION_20250925"."ITL1" T1  ON  T0."LogEntry" = T1."LogEntry"   WHERE (T0."DefinedQty" <> (0 )  OR  (T0."ApplyType" = (10000071 )  AND  T1."LogEntry" IS NOT NULL  )) AND  T0."StockEff" = (1 )) UNION ALL (SELECT MIN(T0."LogEntry") AS "LogEntry", T0."ApplyType", T0."ApplyEntry", T0."ApplyLine", T0."AppSubLine", T0."LocCode", MIN(T0."ItemCode") AS "ItemCode", MAX(T0."ManagedBy") AS "ManagedBy", -1 AS "MdAbsEntry", MAX(T0."DocQty") - SUM(T1."Quantity") AS "Quantity" FROM  "Z_TEST_PRODUCTION_20250925"."OITL" T0   LEFT OUTER  JOIN "Z_TEST_PRODUCTION_20250925"."ITL1" T1  ON  T0."LogEntry" = T1."LogEntry"   WHERE T0."StockQty" <> T0."DefinedQty"  AND  T0."StockEff" = (1 )  AND  T0."DocQty" > (0 )   GROUP BY T0."ApplyType", T0."ApplyEntry", T0."ApplyLine", T0."AppSubLine", T0."LocCode" HAVING MAX(T0."DocQty") <> SUM(T1."Quantity"))) WITH READ ONLY